from __future__ import absolute_import

import ipaddress
import logging

from selenium.common.exceptions import TimeoutException

from taf.selenium.gnb.oam.coam.vdu.common.exceptions import SnapshotException, NoSuchHwElement
from .common_page import CommonPage
from .panels.view import ViewPanel

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class Diagnostic(CommonPage):
    """
    The class corresponding to diagnostic page on selenium_coam_vdu web, all operations under diagnostic
    page will be implemented or added in its corresponding classes.
    """
    _instance_dict = {}

    def __init__(self, driver, version):
        if not self._instance_dict:
            self._instance_dict = {"Snapshot": SnapshotPage(driver, version),
                                   "PMTU Discovery": PMTUDiscovery(driver, version),
                                   "IPConnectivity": IPConnectivity(driver, version)}
        super(Diagnostic, self).__init__(driver, version, self._instance_dict)


class SnapshotPage(object):
    """
    As a class will be called by Diagnostic, all operations Snapshot will be implemented under this class.
    """
    MENU_ROUTE_LIST = ['stethoscope', 'Snapshot']

    def __init__(self, driver, version):
        self._view_panel = SnapshotPageViewPanel(driver, version)

    def set_snapshot_collection(self, coverage, save_location, filter_by_regex, notes):
        self._view_panel.set_snapshot_collection_with_radio_box(coverage, save_location)
        self._view_panel.set_additional_settings_for_snapshot(filter_by_regex, notes)

    def collect_snapshot(self, skip_session_renewal, renewal_password, snapshot_waiting_timeout):
        return self._view_panel.collect_snapshot(skip_session_renewal, renewal_password, snapshot_waiting_timeout)


class SnapshotPageViewPanel(ViewPanel):

    def __init__(self, driver, version):
        self.driver = driver
        super(SnapshotPageViewPanel, self).__init__(driver, version)

    def set_snapshot_collection_with_radio_box(self, coverage, save_location):
        if coverage.lower().strip() == "all logs":
            self.select_radiobox(self.locator.ALL_LOGS_RADIO_BOX)
        else:
            self.select_radiobox(self.locator.MOST_IMPORTANT_LOGS_RADIO_BOX)
        if save_location.lower() == "local":
            self.select_radiobox(self.locator.LOCAL_RADIO_BOX)
        else:
            self.select_radiobox(self.locator.REMOTE_RADIO_BOX)

    def set_additional_settings_for_snapshot(self, filter_by_regex, notes):
        if filter_by_regex is not None:
            self.insert_text_to_enable_element(self.locator.FILTER_BY_REGEX_TEXT_AREA, filter_by_regex)
        if notes is not None:
            self.insert_text_to_enable_element(self.locator.NOTES_TEXT_AREA, notes)

    def _try_collect_snapshot(self, skip_session_renewal, renewal_password, snapshot_waiting_timeout):
        try:
            return self.collect_snapshot_operation(skip_session_renewal, renewal_password, snapshot_waiting_timeout)
        except TimeoutException:
            return self.snapshot_exception()

    def collect_snapshot_operation(self, skip_session_renewal, renewal_password, timeout):
        self.click_enabled_element(self.locator.COLLECT_SNAPSHOT_BUTTON)
        self._handle_session_renewal_pop_up(skip_session_renewal, renewal_password, timeout)
        self._handle_the_toast_messages(timeout)
        self.wait_for_visibility(self.locator.COLLECTION_COMPLETED, timeout)
        return "Snapshot collected successfully"

    def _handle_session_renewal_pop_up(self, skip_session_renewal, renewal_password, timeout=5):
        if self.element_exists(self.locator.DYNAMIC_DIALOG, timeout=5):
            self.click_enabled_element(self.locator.CONTINUE_WITH_OUT_RENEWAL_CHECKBOX)
            self.click_enabled_element(self.locator.OK_BUTTON_XPATH)

    def _handle_the_toast_messages(self, timeout):
        self.wait_for_visibility(self.locator.TOAST_MESSAGE_CONTAINER, timeout)
        if self.get_text(self.locator.TOAST_MESSAGE_CONTAINER, timeout) == "Collect Snapshot operation failed":
            return self.get_text(self.locator.SNAPSHOT_STATUS, timeout)
        self.wait_for_visibility(self.locator.SNAPSHOT_COLLECTION_STARTED, timeout)
        self.wait_for_visibility(self.locator.SNAPSHOT_COLLECTION_FINISHED, timeout)

    def snapshot_exception(self):
        error_text = self.get_text(self.locator.SNAPSHOT_STATUS)
        if error_text:
            return error_text
        raise SnapshotException("Snapshot collection failed returned the error_text message")

    def try_remote_collect_snapshot(self, skip_session_renewal, renewal_password, snapshot_waiting_timeout):
        try:
            return self.collect_snapshot_operation(skip_session_renewal, renewal_password, snapshot_waiting_timeout)
        except TimeoutException:
            self.snapshot_exception()

    def collect_snapshot(self, skip_session_renewal, renewal_password, snapshot_waiting_timeout):
        if self.driver.find_element_by_xpath(self.locator.LOCAL_RADIO_BOX_SELECTED_XPATH).is_selected():
            if self._try_collect_snapshot(skip_session_renewal, renewal_password,
                                          snapshot_waiting_timeout) != "Snapshot collected successfully":
                return "Snapshot collected successfully doesn't appered in the given time {} sec". \
                    format(str(snapshot_waiting_timeout))
            return "Local snapshot collected successfully"
        else:
            return self.try_remote_collect_snapshot(skip_session_renewal, renewal_password, snapshot_waiting_timeout)


class PMTUDiscovery(object):
    """
    As a class will be called by PMTU discovery, all operations PMTU discovery will be implemented under this class.
    """
    MENU_ROUTE_LIST = ['stethoscope', 'PMTU Discovery']

    def __init__(self, driver, version):
        self._view_panel = PMTUDiscoveryViewPanel(driver, version)

    def get_pmtu_discovery_result(self, ip_address_type, source, destination_ip_address, dscp, timeout):
        """
        This keyword is used to run the pmtu test and return result

        :param ip_address_type: str, valid IPv4 or IPv6 IP address
        :param source: str, source of the ip address
        :param destination_ip_address: str, Valid IP4 or IPv6 address
        :param dscp: str,dscp value to be configured
        :param timeout: int, timeout for the element be available to click

        :return: Dict, return the dictionary of test PMTU test result
        """
        return self._view_panel.start_pmtu_discovery_get_result(ip_address_type, source, destination_ip_address,
                                                                dscp, timeout)


class PMTUDiscoveryViewPanel(ViewPanel):
    def __init__(self, driver, version):
        self.driver = driver
        super(PMTUDiscoveryViewPanel, self).__init__(driver, version)

    @staticmethod
    def validate_ip_address(address):
        """
        Checks if it is a valid IPv4 or IPv6 address otherwise, raises value error.

        :param address: Ipv4 or IPv6 address
        """
        ipaddress.ip_address(address.encode().decode())
        logger.debug("given address {}".format(address))

    def start_pmtu_discovery_get_result(self, ip_address_type, source, destination_ip_address, dscp, timeout):
        """

        This keyword is used to run the pmtu test and return result

        :param ip_address_type: str, valid IPv4 or IPv6 IP address
        :param source: str, source of the ip address
        :param destination_ip_address: Str, Valid IP4 or IPv6 address
        :param dscp: str, dscp value to be configured
        :param timeout: int, timeout for the element be available to click

        :return: Dict, return the dictionary of test PMTU test result
        """

        self.validate_ip_address(destination_ip_address)
        if ip_address_type.lower() == "ipv4":
            self.select_radiobox(self.locator.DIAGNOSTIC_IPV4_RADIO_BUTTON)
        elif ip_address_type.lower() == "ipv6":
            self.select_radiobox(self.locator.DIAGNOSTIC_IPV6_RADIO_BUTTON)
        else:
            raise NoSuchHwElement
        self.click_enabled_element(self.locator.SOURCE_IP_ADDRESS_XPATH, timeout)
        self.click_enabled_element(self.locator.CHOOSE_PARTIAL_MATCH_ITEM_FROM_DROP_DOWN.format(source), timeout)
        self.insert_text_to_enable_element(self.locator.DESTINATION_IP_ADDRESS, destination_ip_address, timeout)
        self.insert_text_to_enable_element(self.locator.DSCP, dscp, timeout)
        self.click_enabled_element(self.locator.START_BUTTON_XPATH, timeout)
        self.start_test_and_wait_to_finish(timeout)
        return self.parse_pmtu_test_result()

    def start_test_and_wait_to_finish(self, timeout):
        self.click_enabled_element(self.locator.START_BUTTON_XPATH, timeout)
        self.wait_for_visibility(self.locator.STRAT_BUTTON_DISABELD, timeout)
        self.wait_for_invisibility(self.locator.STRAT_BUTTON_DISABELD, timeout)

    def parse_pmtu_test_result(self):
        result = {}
        for index in range(1, len(self.get_all_matching_elements(self.locator.PMTU_STATUS_TABLE_ROW_XPATH)) + 1):
            if self.element_exists(self.locator.PMTU_STATUS_TABLE_CELL_XPATH.format(index, 2)):
                result[self.get_text(self.locator.PMTU_STATUS_TABLE_CELL_XPATH.format(index, 1))] = \
                    self.get_text(self.locator.PMTU_STATUS_TABLE_CELL_XPATH.format(index, 2))
            else:
                result[self.get_text(self.locator.PMTU_STATUS_TABLE_CELL_XPATH.format(index, 1))] = None
        return result


class IPConnectivity(object):
    """
    As a class will be called by Diagnostic, all operations IP connectivity page will be implemented under this class.
    """
    MENU_ROUTE_LIST = ['stethoscope', 'IP Connectivity']

    def __init__(self, driver, version):
        self._view_panel = IPConnectivityViewPanel(driver, version)

    def start_ip_connectivity_test(self, ip_version, source_address, scope, payload, dscp, ip_address, timeout):
        """
        This keyword is used to start the ip connectivity test
        :param ip_version: str, Version of IP ipv4 or ipv6
        :param scope: str, Scope of the test
        :param source_address: str, Source of the ip address
        :param payload: str, payload length
        :param dscp: str, dscp code
        :param ip_address: Use defined ip address
        :param timeout: int, timeout for the element be available to click
        :return: str, Start test status
        """
        self._view_panel.start_ip_connectivity_test(ip_version, source_address, scope, payload, dscp, ip_address,
                                                    timeout)

    def stop_ip_connectivity_test(self, timeout):
        """
        This keyword will stop the ongoing ip connectivity test.
        :param timeout: int, timeout for the element be available to click

        """
        self._view_panel.stop_ip_connectivity_test(timeout)

    def get_ip_connectivity_test_result(self, timeout):
        """
        This keyword will return the test result of IP connectivity test.

        :param timeout: int, timeout for the element be available to click
        :return: str, test result.
        """
        return self._view_panel.get_ip_connectivity_test_result(timeout)


class IPConnectivityViewPanel(ViewPanel):
    def __init__(self, driver, version):
        self.driver = driver
        super(IPConnectivityViewPanel, self).__init__(driver, version)

    def start_ip_connectivity_test(self, ip_version, source_address, scope, payload, dscp, ip_address, timeout):
        """
        This keyword is used to start the ip connectivity test

        :param ip_version: str, Version of IP ipv4 or ipv6
        :param scope: str, Scope of the test
        :param source_address: str, Source of the ip address
        :param payload: str, payload length
        :param dscp: str, dscp code
        :param ip_address: Use defined ip address
        :param timeout: int, timeout for the element be available to click

        :return: str, Start test status
        """
        if ip_version.lower() == "ipv6":
            self.wait_for_visibility(self.locator.DIAGNOSTIC_IPV6_RADIO_BUTTON, timeout)
            self.click_enabled_element(self.locator.DIAGNOSTIC_IPV6_RADIO_BUTTON, timeout)
        else:
            self.click_enabled_element(self.locator.DIAGNOSTIC_IPV4_RADIO_BUTTON, timeout)
        self.click_enabled_element(self.locator.SOURCE_IP_ADDRESS_XPATH, timeout)
        self.click_enabled_element(self.locator.CHOOSE_ITEM_FROM_DROP_DOWN.format(source_address), timeout)
        self.click_enabled_element(self.locator.SOURCE_IP_ADDRESS_LABEL, timeout)
        self.click_enabled_element(self.locator.SCOPE_XPATH, timeout)
        self.click_enabled_element(self.locator.CHOOSE_ITEM_FROM_DROP_DOWN.format(scope), timeout)
        if scope.lower() == "user defined address":
            self.insert_text_to_enable_element(self.locator.IP_CONNECTIVITY_IP_ADDRESS, ip_address, timeout)
        self.insert_text_to_enable_element(self.locator.PAYLOAD_TEXT_BOX, payload, timeout)
        self.insert_text_to_enable_element(self.locator.DSCP, dscp, timeout)
        self.click_enabled_element(self.locator.START_BUTTON_XPATH, timeout)

    def stop_ip_connectivity_test(self, timeout):
        """
        This keyword will stop the ongoing ip connectivity test.
        :param timeout: int, timeout for the element be available to click
        """
        if not self.element_exists(self.locator.CANCEL_BUTTON_DISABELD, timeout):
            self.click_enabled_element(self.locator.CANCEL_BUTTON_XPATH, timeout)

    def get_ip_connectivity_test_result(self, timeout):
        """
        This keyword will return the ip connectivity test result.
        :param timeout: int, timeout for the element be available to click

        :return: dict, ip connectivity test result
        """
        table_body = []
        header = self.get_fields_info_from_row(self.locator.IP_CONNECTIVITY_RESULT_TABLE.format("thead//th"), timeout)
        table_rows = self.get_all_matching_elements(self.locator.IP_CONNECTIVITY_RESULT_TABLE.format("tbody//tr"))
        for row in range(1, len(table_rows) + 1):
            table_body.append(self.get_fields_info_from_row(self.locator.IP_CONNECTIVITY_RESULT_TABLE.
                                                            format("tbody//tr[{}]//td").format(row), timeout))
        return self.zip_table_result(header, table_body)

    @staticmethod
    def zip_table_result(header, table_body):
        final_result = []
        for row in range(0, len(table_body)):
            final_result.append(dict(zip(header, table_body[row])))
        return final_result
